using Astronomy.MediaFactory.Core.KnowledgeFoundation.Catalog;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Catalog;
public sealed class AstronomyKnowledgeCatalogTests{[Fact]public void KnowledgeCatalog_supports_exact_lookup_and_kind_only_access(){var cat=KnowledgeCatalogFixture.Catalog();Assert.NotEmpty(cat.Snapshot.Entries);var first=cat.Snapshot.Entries[0];Assert.True(cat.TryGet(first.Id,out var found));Assert.Same(first,found);Assert.False(cat.TryGet(new(first.Id.Kind,"unknown"),out _));Assert.Equal(cat.GetByKind(first.Kind),cat.Snapshot.Entries.Where(e=>e.Kind==first.Kind));Assert.Throws<ArgumentOutOfRangeException>(()=>cat.GetByKind((AstronomyKnowledgeCatalogEntryKind)999));Assert.DoesNotContain(typeof(IAstronomyKnowledgeCatalog).GetMethods(),m=>m.Name.Contains("Query")||m.Name.Contains("Search"));}}
